// Ported from the Node app's Sequelize model ExamGroup (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class ExamGroupConfiguration : IEntityTypeConfiguration<ExamGroup>
{
    public void Configure(EntityTypeBuilder<ExamGroup> builder)
    {
        builder.ToTable("exam_groups");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.ClassId).HasColumnName("class_id");
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.HasIndex(e => new { e.ClassId, e.Name }).IsUnique().HasDatabaseName("uq_exam_group");
        builder.HasOne(e => e.SchoolClass).WithMany(p => p.ExamGroups).HasForeignKey(e => e.ClassId).OnDelete(DeleteBehavior.NoAction);
    }
}
